python - <<'PY'
import csv, json
from datetime import datetime, timedelta
from zoneinfo import ZoneInfo

def parse_utc(s):
    return datetime.fromisoformat(s).replace(tzinfo=ZoneInfo('UTC'))
la=ZoneInfo('America/Los_Angeles')
start=datetime(2026,11,1,0,0,tzinfo=la)
end=datetime(2026,12,1,0,0,tzinfo=la)
flags=set()
# get start reg
start_reg=None
with open('/app/readings.csv',newline='') as f:
    r=csv.DictReader(f)
    for row in r:
        if parse_utc(row['ts']).astimezone(la)==start:
            start_reg=float(row['register_kwh']);break
if start_reg is None:
    out={'status':'cannot_determine','reason':'missing reading exactly at local month start boundary','flags':['missing_boundary_reading']}
else:
    prev_reg=start_reg
    cons=0.0
    seen=set(); dup=0
    expected=[]
    cur=start+timedelta(hours=1)
    while cur<=end:
        expected.append(cur);cur+=timedelta(hours=1)
    with open('/app/readings.csv',newline='') as f:
        r=csv.DictReader(f)
        for row in r:
            loc=parse_utc(row['ts']).astimezone(la)
            if not (start < loc <= end):
                continue
            if loc in seen: dup+=1
            seen.add(loc)
            reg=float(row['register_kwh'])
            delta=reg-prev_reg
            if delta>=-1e-6:
                cons+=delta
            else:
                flags.add('meter_reset')
                cons+=reg
            prev_reg=reg
    if dup: flags.add('duplicate_local_hour')
    missing=[t for t in expected if t not in seen]
    if missing: flags.add('missing_hours')
    out={'answer':round(cons,1),'flags':sorted(flags)}

with open('/app/answer.json','w') as f:
    json.dump(out,f)
print(out)
PY
cat /app/answer.json
